## Steps

- [ ] 1. Create `test/weekly-csat-summary.test.js` with a failing test:
      ```js
      'use strict';
      const test = require('node:test');
      const assert = require('node:assert/strict');
      const fs = require('node:fs');
      const os = require('node:os');
      const path = require('node:path');
      const { createStore } = require('../src/store');
      const { createTicket, assignTicket, resolveTicket, rateTicket } = require('../src/tickets');
      const { weeklyCsatSummary } = require('../src/jobs/weekly-csat-summary');

      const DAY = 24 * 60 * 60 * 1000;
      const at = (days) => new Date(Date.UTC(2026, 0, 1) + days * DAY);

      function ratedTicket(store, agentId, score, ratedAt) {
        const t = createTicket(store, { orgId: 1, customerId: 7, subject: 'x', body: 'x', now: at(0) });
        assignTicket(store, t.id, agentId);
        resolveTicket(store, t.id, agentId, { now: at(0) });
        rateTicket(store, t.id, score, { now: ratedAt });
        return t;
      }

      test('the weekly summary counts ratings from the past 7 days and averages them', () => {
        const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'helpdesk-csat-'));
        try {
          const store = createStore();
          ratedTicket(store, 41, 5, at(10));
          ratedTicket(store, 41, 4, at(11));
          ratedTicket(store, 41, 1, at(12));
          ratedTicket(store, 41, 5, at(5)); // 8 days before "now" (at(13)): not counted
          const out = weeklyCsatSummary(store, { now: at(13), dir });
          const rows = JSON.parse(fs.readFileSync(out.file, 'utf8'));
          assert.deepEqual(rows, [{ owner_id: 41, ratings: 3, average: 3.33 }]);
        } finally {
          fs.rmSync(dir, { recursive: true, force: true });
        }
      });
      ```
      Evidence: `npm test` fails (`Cannot find module '../src/jobs/weekly-csat-summary'`).
- [ ] 2. Create `src/jobs/weekly-csat-summary.js`:
      ```js
      'use strict';
      // Nightly. Writes exports/csat-summary.json: one row per agent, counting ratings their tickets received in
      // the past 7 days and the average score, so team leads don't have to tally this by hand.
      const fs = require('node:fs');
      const path = require('node:path');

      const EXPORT_DIR = path.join(__dirname, '..', '..', 'exports');
      const WINDOW_DAYS = 7;
      const DAY = 24 * 60 * 60 * 1000;

      function weeklyCsatSummary(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
        const byOwner = new Map();
        for (const t of store.listTickets()) {
          if (t.rating_score == null || !t.owner_id) continue;
          if (now.getTime() - new Date(t.rated_at).getTime() >= WINDOW_DAYS * DAY) continue;
          const scores = byOwner.get(t.owner_id) || [];
          scores.push(t.rating_score);
          byOwner.set(t.owner_id, scores);
        }
        const rows = [...byOwner.entries()].map(([owner_id, scores]) => ({
          owner_id,
          ratings: scores.length,
          average: Math.round((scores.reduce((a, b) => a + b, 0) / scores.length) * 100) / 100,
        }));
        fs.mkdirSync(dir, { recursive: true });
        const file = path.join(dir, 'csat-summary.json');
        fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
        return { file, rows: rows.length };
      }

      module.exports = { weeklyCsatSummary, WINDOW_DAYS, EXPORT_DIR };
      ```
      Evidence: `npm test` — the test from step 1 passes; paste the summary line.
- [ ] 3. Add a second test for the zero-ratings case (an agent with no ratings in the window produces no row, not
