        const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'helpdesk-csat-'));
        try {
          const store = createStore();
          ratedTicket(store, 41, 5, at(5)); // 8 days before "now" (at(13))
          const out = weeklyCsatSummary(store, { now: at(13), dir });
          assert.equal(out.rows, 0);
          assert.deepEqual(JSON.parse(fs.readFileSync(out.file, 'utf8')), []);
        } finally {
          fs.rmSync(dir, { recursive: true, force: true });
        }
      });
      ```
      Evidence: `npm test` passes.
- [ ] 4. Commit: `git commit -am "add nightly weekly CSAT summary job"`.
      Evidence: `git log -1 --stat` pasted.

